import type { ProgramsWorkflowParams } from "./programs/ProgramsWorkflow";
import type { ScrapeWorkflowParams } from "./scrape/ScrapeWorkflow";

/**
 * Everything the catalog Worker reads from its environment, as wrangler.jsonc
 * binds it. Hand-written rather than generated by `wrangler types`: the Worker
 * is small, and a generated file would add a drift check for no gain.
 */
export interface CatalogEnv {
  /** `development`, `staging` or `production`: set by wrangler.jsonc's per-environment `vars`. */
  readonly DEPLOY_ENV?: string;
  /**
   * The database in the deployed environments: Hyperdrive in front of the
   * platform project's direct endpoint, shared with the platform Worker. The
   * read API and the scrape both use it; the API drops to the read-only
   * `catalog_reader` role per transaction (src/db/reader.ts).
   */
  readonly HYPERDRIVE?: Hyperdrive;
  /** Local development only (`.dev.vars` or `--var`): a direct connection string. */
  readonly DB_URL?: string;
  /** The daily registrar scrape (src/scrape/ScrapeWorkflow.ts). */
  readonly SCRAPE_WORKFLOW: Workflow<ScrapeWorkflowParams>;
  /** The daily Bulletin program sync (src/programs/ProgramsWorkflow.ts). */
  readonly PROGRAMS_WORKFLOW: Workflow<ProgramsWorkflowParams>;
  /** Per-IP limit for every endpoint. */
  readonly CATALOG_LIMITER?: RateLimit;
  /** Per-IP limit for `/search`, tighter. */
  readonly SEARCH_LIMITER?: RateLimit;
  /**
   * The platform's Sentry DSN, a Worker secret. The catalog reports to the
   * platform project, tagged `worker:catalog`; it has no project of its own
   * yet. Empty means no Sentry, which is the local-development state.
   */
  readonly PLATFORM_SENTRY_DSN?: string;
  /** The deploy's git SHA, passed as a `--var` on `wrangler deploy`. */
  readonly SENTRY_RELEASE?: string;
}
